import {test} from 'node:test';import assert from 'node:assert/strict';import {calculate,filterEnquiries,samples,validateAppointment,load,KEY} from '../src/domain.js';
test('roofing repair and replacement ranges',()=>{assert.deepEqual([calculate({service:'roofing',work:'Repair',area:40}).low,calculate({service:'roofing',work:'Repair',area:40}).high],[1264,1896]);assert.equal(calculate({service:'roofing',work:'Replacement',area:10}).total,1130);});
test('roughcasting rates',()=>{assert.equal(calculate({service:'roughcasting',work:'Repair',area:10}).total,460);assert.equal(calculate({service:'roughcasting',work:'Full application',area:10}).total,830);});
test('window and door quantities',()=>{assert.equal(calculate({service:'openings',windows:4,doors:1}).total,2710);for(const [windows,doors] of [[0,0],[-1,1],[1.5,1],[51,1],[1,21]])assert.throws(()=>calculate({service:'openings',windows,doors}));});
test('reject invalid area or work',()=>{for(const area of [0,-1,1001,'no',Infinity])assert.throws(()=>calculate({service:'roofing',work:'Repair',area}));assert.throws(()=>calculate({service:'roofing',work:'other',area:10}));});
test('appointment must be future and an offered time',()=>{assert.ok(validateAppointment('2027-01-02','11:00','2027-01-01'));for(const [d,t] of [['2027-01-01','11:00'],['2026-12-31','11:00'],['2027-01-02','12:00'],['junk','11:00']])assert.equal(validateAppointment(d,t,'2027-01-01'),false);});
test('search and combined filters',()=>{const rows=samples();assert.equal(filterEnquiries(rows,'GLASGOW').length,1);assert.equal(filterEnquiries(rows,'','roofing','New').length,1);assert.equal(filterEnquiries(rows,'','roofing','Closed').length,0);});
test('sample seeding, persistence and corruption',()=>{assert.equal(load({getItem:()=>null}).length,3);assert.deepEqual(load({getItem:()=> '[]'}),[]);assert.throws(()=>load({getItem:()=>'{'}));assert.equal(KEY,'hearth-demo-enquiries-v1');});
